mapper.select:
select instrument_type,sum(d_value) as ddValue,sum(dc_value) as dcValue,sum(zh_value) as zhValue,sum(f_value) as fValue,sum(p_value)
as pValue,sum(g_value) as gValue,sum(j_value) as jValue
from energy_daily_usage
where deleted = 0

    and instrument_type = #{param.instrumentType}


    and stat_date >= #{param.period.begin}


    and stat_date <= #{param.period.end}

select sum(d_value) as dValue,sum(dc_value) as dcValue,sum(zh_value) as zhValue
from energy_daily_usage
where deleted = 0

    and instrument_type = #{param.instrumentType}


    and stat_date >= #{param.period.begin}


    and stat_date <= #{param.period.end}

select instrument_type,sum(d_value) as dValue,sum(dc_value) as dcValue,sum(zh_value) as zhValue
from energy_daily_usage
where deleted = 0

    and stat_date >= #{param.period.begin}


    and stat_date <= #{param.period.end}

group by instrument_type;

select DATE_FORMAT(stat_date,#{param.groupFormat}) as time,sum(d_value) as value,
sum(dc_value) as dcValue,sum(zh_value) as zhValue
from energy_daily_usage
where deleted = 0

    and instrument_type = #{param.instrumentType}


    and stat_date >= #{param.period.begin}


    and stat_date <= #{param.period.end}

group by time

select DATE_FORMAT(stat_date,#{param.groupFormat}) as time,instrument_type_name as name,
sum(d_value) as value,sum(dc_value) as dcValue,sum(zh_value) as zhValue
from energy_daily_usage
where deleted = 0

    and instrument_type = #{param.instrumentType}


    and stat_date >= #{param.period.begin}


    and stat_date <= #{param.period.end}

group by time,name
